    {
      "topic": "trigger",
      "statement": "The after-source parser checks query depth while parsing filter predicates and step predicates. Exceeding xpath_ast_depth_limit calls error_rec().",
      "evidence": [
        {"unit_id": "u-bef75e2a7b8ed4d6ba70", "start_line": 11581, "end_line": 11593, "role": "primary", "dependency_reason": ""},
